<?php namespace App\Http\Controllers; use App\Models\Booking; use Illuminate\Http\Request; use Symfony\Component\HttpFoundation\StreamedResponse;
class ReportController extends Controller { private function q(Request $r){return Booking::with(['room','user'])->when($r->from,fn($q,$v)=>$q->whereDate('start_at','>=',$v))->when($r->to,fn($q,$v)=>$q->whereDate('start_at','<=',$v))->when($r->room,fn($q,$v)=>$q->where('meeting_room_id',$v))->when($r->status,fn($q,$v)=>$q->where('status',$v));} public function index(Request $r){$bookings=$this->q($r)->latest('start_at')->paginate(20)->withQueryString();return view('reports.index',compact('bookings'));} public function csv(Request $r):StreamedResponse{$bookings=$this->q($r)->get();return response()->streamDownload(function()use($bookings){$o=fopen('php://output','w');fputcsv($o,['Kode','Ruangan','Pemohon','Judul','Mulai','Selesai','Status']);foreach($bookings as $b)fputcsv($o,[$b->booking_code,$b->room->name,$b->user->name,$this->safe($b->title),$b->start_at,$b->end_at,$b->status]);fclose($o);},'laporan-booking.csv',['Content-Type'=>'text/csv']);} private function safe($v){return preg_match('/^[=+\-@]/',$v)?"'$v":$v;} }
